function Button({ children, variant = 'primary', className = '', ...props }: { children: ReactNode; variant?: 'primary' | 'secondary' | 'ghost' | 'accent'; className?: string; [key: string]: unknown }) {
  const styles = { primary: 'bg-primary text-primary-foreground shadow-[0_5px_0_hsl(var(--primary)/.22)] hover:-translate-y-0.5', secondary: 'border border-border bg-card text-foreground hover:bg-muted', ghost: 'text-muted-foreground hover:bg-muted hover:text-foreground', accent: 'bg-accent text-accent-foreground shadow-[0_5px_0_hsl(var(--accent)/.22)] hover:-translate-y-0.5' };
  return <button className={`focus-ring inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition-all active:translate-y-0 ${styles[variant]} ${className}`} {...props}>{children}</button>;
}

function StatusPill({ status }: { status: string }) { return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold ${statusTone[status] || statusTone.saved}`} data-testid={`status-${status}`}>{statusLabels[status] || status}</span>; }

function ScoreRing({ score, size = 'md' }: { score: number; size?: 'sm' | 'md' | 'lg' }) {
  const dims = size === 'lg' ? 'h-28 w-28' : size === 'sm' ? 'h-12 w-12' : 'h-20 w-20';
  return <div className={`relative grid ${dims} shrink-0 place-items-center rounded-full`} style={{ background: `conic-gradient(hsl(var(--accent)) ${score * 3.6}deg, hsl(var(--muted)) 0deg)` }} data-testid={`score-${score}`}>
    <div className="grid h-[calc(100%-8px)] w-[calc(100%-8px)] place-items-center rounded-full bg-card"><span className={`${size === 'lg' ? 'text-3xl' : size === 'sm' ? 'text-sm' : 'text-xl'} font-bold tracking-tight`}>{score}<span className="text-xs font-medium text-muted-foreground">%</span></span></div>
  </div>;
}

