function AuthScreen() {
  const { isLoading, isAuthenticated, signIn, signUp } = useAuth();
  const [mode, setMode] = useState<'signin' | 'signup'>(
    new URLSearchParams(window.location.search).get('mode') === 'signup' ? 'signup' : 'signin',
  );
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [error, setError] = useState('');
  const [confirmation, setConfirmation] = useState(false);

  useEffect(() => {
    if (isAuthenticated) window.location.href = '/dashboard';
  }, [isAuthenticated]);

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    setError('');
    setConfirmation(false);
    try {
      if (mode === 'signin') {
        await signIn(email, password);
      } else {
        const result = await signUp(email, password, firstName, lastName);
        if (result.requiresEmailConfirmation) setConfirmation(true);
      }
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : 'Something went wrong.');
    }
  };

  return <div className="min-h-[100dvh] bg-background px-5 py-8 md:px-10"><div className="mx-auto max-w-6xl"><Logo /><div className="mx-auto mt-16 grid max-w-4xl gap-12 md:grid-cols-[.9fr_1.1fr] md:items-center"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-primary">Your career workspace</p><h1 className="mt-4 font-display text-5xl font-bold leading-[.95] tracking-[-.07em] md:text-6xl">{mode === 'signin' ? 'Welcome back to your next move.' : 'Make your next move easier to find.'}</h1><p className="mt-6 max-w-md text-base leading-7 text-muted-foreground">Sign in to keep your applications, recommendations, and interview practice with you on every device.</p><Link href="/" className="mt-7 inline-flex text-sm font-bold text-primary hover:underline">Back to CareerGenie</Link></div><section className="rounded-3xl border border-border bg-card p-6 shadow-xl md:p-8"><div className="flex gap-1 rounded-xl bg-muted p-1"><button className={`flex-1 rounded-lg px-3 py-2 text-sm font-bold ${mode === 'signin' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`} onClick={() => setMode('signin')} type="button">Sign in</button><button className={`flex-1 rounded-lg px-3 py-2 text-sm font-bold ${mode === 'signup' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`} onClick={() => setMode('signup')} type="button">Create account</button></div><h2 className="mt-8 font-display text-2xl font-bold">{mode === 'signin' ? 'Pick up where you left off.' : 'Start your private workspace.'}</h2><p className="mt-2 text-sm text-muted-foreground">{mode === 'signin' ? 'Your work is ready when you are.' : 'Your work follows your account, not one browser.'}</p>{confirmation ? <div className="mt-6 rounded-2xl bg-[#e7f4ef] p-4 text-sm leading-6 text-[#236a58]">Check your inbox to confirm your email. Once confirmed, come back here to sign in.</div> : <form onSubmit={submit} className="mt-6 space-y-4">{mode === 'signup' && <div className="grid gap-4 sm:grid-cols-2"><Field label="First name" value={firstName} onChange={setFirstName} placeholder="Ananya" testId="input-signup-first-name" /><Field label="Last name" value={lastName} onChange={setLastName} placeholder="Tiwari" testId="input-signup-last-name" /></div>}<Field label="Email" value={email} onChange={setEmail} placeholder="you@example.com" required testId="input-auth-email" /><label className="block"><span className="mb-2 block text-xs font-bold">Password</span><input required minLength={6} type="password" autoComplete={mode === 'signin' ? 'current-password' : 'new-password'} value={password} onChange={(event) => setPassword(event.target.value)} placeholder="At least 6 characters" className="w-full rounded-xl border border-input bg-background px-3.5 py-3 text-sm outline-none transition-shadow focus:border-primary focus:ring-2 focus:ring-primary/10" data-testid="input-auth-password" /></label>{error && <p className="rounded-xl bg-[#fae8e6] px-3 py-2.5 text-sm text-[#9b423b]" role="alert">{error}</p>}<Button type="submit" className="w-full" disabled={isLoading} data-testid="button-auth-submit">{isLoading ? 'Working…' : mode === 'signin' ? 'Sign in' : 'Create my workspace'} <ArrowRight size={16} /></Button></form>}</section></div></div></div>;
}

function FeatureCard({ number, icon: FeatureIcon, title, text, color }: { number: string; icon: Icon; title: string; text: string; color: string }) { return <div className={`rounded-3xl p-6 md:p-8 ${color}`}><div className="flex items-center justify-between"><span className="font-mono text-xs font-bold opacity-50">{number}</span><FeatureIcon size={20} /></div><h3 className="mt-16 font-display text-2xl font-bold tracking-[-.04em]">{title}</h3><p className="mt-3 text-sm leading-6 text-foreground/65">{text}</p></div>; }

function PageHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { return <div className="flex flex-col gap-5 md:flex-row md:items-end md:justify-between"><div>{eyebrow && <p className="mb-3 text-xs font-bold uppercase tracking-[.18em] text-primary">{eyebrow}</p>}<h1 className="font-display text-4xl font-bold leading-none tracking-[-.06em] md:text-5xl" data-testid="text-page-title">{title}</h1>{description && <p className="mt-3 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{action}</div>; }

function Metric({ label, value, note, icon: MetricIcon, tone = 'primary' }: { label: string; value: string | number; note: string; icon: Icon; tone?: 'primary' | 'accent' | 'mint' }) { const iconTone = tone === 'accent' ? 'bg-[#fff0e9] text-[#ad4c31]' : tone === 'mint' ? 'bg-[#e7f4ef] text-[#236a58]' : 'bg-[#eeeafd] text-[#5140a2]'; return <div className="rounded-2xl border border-border bg-card p-5 shadow-sm"><div className="flex items-start justify-between"><div><p className="text-xs font-bold text-muted-foreground">{label}</p><p className="mt-3 font-display text-3xl font-bold tracking-[-.05em]" data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`}>{value}</p></div><span className={`grid h-9 w-9 place-items-center rounded-xl ${iconTone}`}><MetricIcon size={17} /></span></div><p className="mt-3 text-xs text-muted-foreground">{note}</p></div>; }

  function ApplicationRow({ app, onStatus }: { app: Application; onStatus?: (id: string, status: string) => void }) { return <div className="group flex flex-col gap-4 border-b border-border py-4 last:border-0 sm:flex-row sm:items-center" data-testid={`row-application-${app.id}`}><Link href={`/applications/${app.id}`} className="flex min-w-0 flex-1 items-center gap-3 focus-ring" data-testid={`link-application-${app.id}`}><div className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl text-xs font-bold" style={{ background: `${app.accent || '#8C7EE5'}2c`, color: app.accent || '#5140a2' }}>{app.initials || app.companyName.slice(0, 2).toUpperCase()}</div><div className="min-w-0"><p className="truncate text-sm font-bold">{app.jobTitle}</p><p className="truncate text-xs text-muted-foreground">{app.companyName} · {app.location || 'Location flexible'}</p></div></Link><div className="flex items-center gap-4 pl-14 sm:pl-0"><div className="hidden text-right sm:block"><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Match</p><p className="text-sm font-bold">{app.matchScore}%</p></div><StatusPill status={app.status} />{onStatus && <select className="rounded-lg border-0 bg-muted px-2 py-1.5 text-xs font-bold text-muted-foreground outline-none" value={app.status} onChange={(e) => onStatus(app.id, e.target.value)} aria-label={`Update status for ${app.jobTitle}`} data-testid={`select-status-${app.id}`}><option value="saved">Saved</option><option value="applied">Applied</option><option value="screening">Screening</option><option value="interview">Interview</option><option value="offer">Offer</option><option value="rejected">Not moving forward</option></select>}</div></div>; }

function Dashboard() {
  const dashboardQuery = useGetDashboard();
  const summary: DashboardSummary = dashboardQuery.data || { firstName: 'there', applications: 0, interviews: 0, offers: 0, readiness: 78, recentApplications: [] };
  const recent = summary.recentApplications || [];
  const nextApplication = recent[0];
  return <Shell><div className="animate-reveal space-y-8"><PageHeading eyebrow="Tuesday, March 18" title={`Good morning, ${summary.firstName}.`} description="Your next best move is waiting for you." action={<Link href="/applications/new" className="focus-ring inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-bold text-primary-foreground shadow-[0_5px_0_hsl(var(--primary)/.22)] transition-transform hover:-translate-y-0.5" data-testid="link-dashboard-new"><Plus size={16} /> Add a target</Link>} /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Active applications" value={summary.applications} note="Keep the momentum warm" icon={BriefcaseBusiness} /><Metric label="Interview paths" value={summary.interviews} note="1 needs a practice run" icon={Mic2} tone="accent" /><Metric label="Offers" value={summary.offers} note="There’s room for one more" icon={Zap} tone="mint" /><Metric label="Readiness" value={`${summary.readiness}%`} note="Up 8 points this week" icon={Gauge} /></div><div className="grid gap-6 lg:grid-cols-[1.45fr_.75fr]"><section className="rounded-3xl border border-border bg-card p-5 shadow-sm md:p-7"><div className="flex items-center justify-between"><div><h2 className="font-display text-xl font-bold tracking-[-.04em]">Recent momentum</h2><p className="mt-1 text-xs text-muted-foreground">The roles getting your attention lately.</p></div><Link href="/applications" className="text-xs font-bold text-primary hover:underline" data-testid="link-view-all-applications">View all <ChevronRight className="inline" size={14} /></Link></div><div className="mt-5">{recent.length ? recent.map((app) => <ApplicationRow key={app.id} app={app} />) : <p className="py-8 text-sm text-muted-foreground">Your first target is one clear step away.</p>}</div></section><section className="relative overflow-hidden rounded-3xl bg-[#2e2855] p-6 text-[#f8f2e8]"><div className="absolute -right-10 -top-10 h-36 w-36 rounded-full bg-[#8f82e6]/30 blur-2xl" /><Sparkles className="text-[#f3b38d]" size={22} /><p className="mt-8 text-xs font-bold uppercase tracking-[.18em] text-[#c7bff2]">Readiness pulse</p><h2 className="mt-3 font-display text-3xl font-bold leading-tight tracking-[-.05em]">You’re closer than your doubt says.</h2><div className="mt-8 flex items-end justify-between"><span className="text-6xl font-bold tracking-[-.08em]">{summary.readiness}</span><span className="pb-2 text-sm text-[#c7bff2]">/ 100</span></div><div className="mt-3 h-2 rounded-full bg-white/15"><div className="h-full rounded-full bg-[#f3b38d]" style={{ width: `${summary.readiness}%` }} /></div>{nextApplication && <Link href={`/applications/${nextApplication.id}/interview`} className="mt-8 inline-flex items-center gap-2 text-sm font-bold text-[#f3b38d] hover:text-white" data-testid="link-practice-interview">Practice next <ArrowRight size={15} /></Link>}</section></div><section className="rounded-3xl border border-border bg-[#f1ebe6] p-5 md:p-7"><div className="flex flex-col gap-5 md:flex-row md:items-center md:justify-between"><div className="flex items-center gap-4"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-accent text-accent-foreground"><Lightbulb size={22} /></div><div><h3 className="font-display text-lg font-bold">One useful thing</h3><p className="mt-1 max-w-xl text-sm text-muted-foreground">Candidates who practice their opening story feel 34% more composed in the first five minutes. Try yours before your next application.</p></div></div>{nextApplication && <Link href={`/applications/${nextApplication.id}/interview`} className="focus-ring inline-flex items-center gap-2 text-sm font-bold text-primary" data-testid="link-take-a-minute">Take a minute <ArrowRight size={15} /></Link>}</div></section></div></Shell>;
}

function Applications() {
  const { data, isLoading, isError, refetch } = useGetApplications();
  const update = useUpdateApplication();
  const [filter, setFilter] = useState('all');
  const [search, setSearch] = useState('');
  const apps: Application[] = data ? (data as Application[]) : [];
  const filtered = apps.filter((a: Application) => (filter === 'all' || a.status === filter) && `${a.jobTitle} ${a.companyName}`.toLowerCase().includes(search.toLowerCase()));
  const handleStatus = (id: string, status: string) => update.mutate({ applicationId: id, data: { status: status as typeof ApplicationStatus[keyof typeof ApplicationStatus] } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetApplicationsQueryKey() }) });
  return <Shell><div className="animate-reveal space-y-7"><PageHeading eyebrow="Your pipeline" title="Applications" description="A gentle place to keep every opportunity moving." action={<Link href="/applications/new" className="focus-ring inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-bold text-primary-foreground shadow-[0_5px_0_hsl(var(--primary)/.22)]" data-testid="link-applications-new"><Plus size={16} /> New target</Link>} /><div className="flex flex-col gap-3 rounded-2xl border border-border bg-card p-3 shadow-sm md:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={16} /><input value={search} onChange={(e) => setSearch(e.target.value)} className="w-full rounded-xl bg-muted py-2.5 pl-10 pr-3 text-sm outline-none ring-primary/20 focus:ring-2" placeholder="Search roles or companies" data-testid="input-search-applications" /></div><div className="flex items-center gap-2 overflow-x-auto"><Filter size={15} className="ml-2 shrink-0 text-muted-foreground" />{['all', 'saved', 'applied', 'screening', 'interview', 'offer'].map((item) => <button key={item} onClick={() => setFilter(item)} className={`shrink-0 rounded-lg px-3 py-2 text-xs font-bold transition-colors ${filter === item ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted'}`} data-testid={`filter-${item}`}>{item === 'all' ? 'All' : statusLabels[item]}</button>)}</div></div>{isLoading && !data ? <LoadingState /> : isError && !data && !apps.length ? <ErrorState onRetry={() => refetch()} /> : <section className="rounded-3xl border border-border bg-card p-5 shadow-sm md:p-7"><div className="mb-3 flex items-center justify-between"><div><p className="text-sm font-bold">{filtered.length} {filtered.length === 1 ? 'target' : 'targets'}</p><p className="text-xs text-muted-foreground">Sorted by most recently updated</p></div><button className="rounded-lg p-2 text-muted-foreground hover:bg-muted" data-testid="button-sort-applications"><ChevronDown size={17} /></button></div>{filtered.length ? filtered.map((app: Application) => <ApplicationRow key={app.id} app={app} onStatus={handleStatus} />) : <div className="py-16 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-muted text-muted-foreground"><Search size={22} /></div><h3 className="mt-4 font-display text-lg font-bold">No targets in this view</h3><p className="mt-1 text-sm text-muted-foreground">Try another filter or add a new role to your constellation.</p></div>}</section>}</div></Shell>;
}

function NewApplication() {
  const [, setLocation] = useLocation();
  const create = useCreateApplication();
  const resumesQuery = useGetResumes({ query: { staleTime: 30_000 } });
  const requestUpload = useRequestResumeUploadUrl();
  const [form, setForm] = useState({ jobTitle: '', companyName: '', location: '', sourceUrl: '', description: '' });
  const [mode, setMode] = useState<'url' | 'paste'>('url');
  const [selectedResumeId, setSelectedResumeId] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [uploadError, setUploadError] = useState('');
  const [processingState, setProcessingState] = useState<'idle' | 'uploading' | 'extracting' | 'saving'>('idle');
  const resumes = (resumesQuery.data || []) as SavedResume[];

  useEffect(() => {
    if (!selectedResumeId && resumes[0]) setSelectedResumeId(resumes[0].id);
  }, [resumes, selectedResumeId]);

  const selectFile = (nextFile: File | null) => {
    setFile(nextFile);
    setUploadError('');
    if (nextFile) setSelectedResumeId('');
  };

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    setUploadError('');
    try {
      let resumeData: Record<string, unknown> = {};
      if (file) {
        if (file.size > 10 * 1024 * 1024) {
          throw new Error('Choose a CV smaller than 10 MB.');
        }
        setProcessingState('uploading');
        const upload = await requestUpload.mutateAsync({
          data: { name: file.name, size: file.size, contentType: file.type || 'application/octet-stream' },
        });
        const uploaded = await fetch(upload.uploadURL, {
          method: 'PUT',
          headers: { 'Content-Type': file.type || 'application/octet-stream' },
          body: file,
        });
        if (!uploaded.ok) throw new Error('The CV upload did not complete. Please try again.');
        setProcessingState('extracting');
        resumeData = {
          resumeName: file.name,
          resumeFileUrl: upload.objectPath,
          resumeFileType: file.type || 'application/octet-stream',
        };
      } else if (selectedResumeId) {
        resumeData.resumeId = selectedResumeId;
      }
      setProcessingState('saving');
      const result = await create.mutateAsync({
        data: {
          jobTitle: form.jobTitle,
          companyName: form.companyName,
          location: form.location || undefined,
          sourceUrl: mode === 'url' ? form.sourceUrl || null : null,
          description: mode === 'paste' ? form.description : undefined,
          ...resumeData,
        },
      });
      setLocation(`/applications/${(result as Application).id}`);
    } catch (error) {
      setUploadError(error instanceof Error ? error.message : 'Unable to create this workspace.');
    } finally {
      setProcessingState('idle');
    }
  };

  const processingMessage = processingState === 'uploading'
    ? 'Uploading your CV…'
    : processingState === 'extracting'
      ? 'Reading your CV and organizing its sections…'
      : processingState === 'saving'
        ? 'Saving your workspace…'
        : '';
  return <Shell><div className="mx-auto max-w-4xl animate-reveal"><Link href="/applications" className="inline-flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-foreground" data-testid="link-back-applications"><ChevronRight className="rotate-180" size={15} /> Back to applications</Link><div className="mt-8"><PageHeading eyebrow="New target workspace" title="Give the genie a role to work with." description="Start with a link or paste the job description. We’ll turn it into a focused plan." /></div><form onSubmit={submit} className="mt-9 space-y-6"><section className="rounded-3xl border border-border bg-card p-5 shadow-sm md:p-8"><div className="grid gap-5 md:grid-cols-2"><Field label="Job title" value={form.jobTitle} onChange={(v) => setForm({ ...form, jobTitle: v })} placeholder="e.g. Product Designer" required testId="input-job-title" /><Field label="Company" value={form.companyName} onChange={(v) => setForm({ ...form, companyName: v })} placeholder="e.g. Atlas" required testId="input-company-name" /><Field label="Location" value={form.location} onChange={(v) => setForm({ ...form, location: v })} placeholder="Remote, city, or hybrid" testId="input-location" /></div><div className="mt-7 flex items-center gap-1 border-b border-border"><button type="button" onClick={() => setMode('url')} className={`border-b-2 px-3 py-3 text-sm font-bold ${mode === 'url' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground'}`} data-testid="button-job-url-mode">Job link</button><button type="button" onClick={() => setMode('paste')} className={`border-b-2 px-3 py-3 text-sm font-bold ${mode === 'paste' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground'}`} data-testid="button-paste-description-mode">Paste description</button></div>{mode === 'url' ? <div className="relative mt-5"><Linkedin className="absolute left-3 top-3.5 text-muted-foreground" size={17} /><input className="w-full rounded-xl border border-input bg-background px-10 py-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/10" value={form.sourceUrl} onChange={(e) => setForm({ ...form, sourceUrl: e.target.value })} placeholder="https://www.linkedin.com/jobs/view/..." data-testid="input-job-url" /><p className="mt-2 text-xs text-muted-foreground">We’ll read the public details and keep the source attached to this workspace.</p></div> : <textarea className="mt-5 min-h-40 w-full resize-y rounded-xl border border-input bg-background p-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/10" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="Paste the role description here..." data-testid="input-job-description" />}</section><section className="rounded-3xl border border-border bg-card p-5 shadow-sm md:p-8"><div className="flex items-start justify-between gap-4"><div><h2 className="font-display text-xl font-bold">Choose your CV</h2><p className="mt-1 text-sm text-muted-foreground">Saved CVs stay available when you sign in on another device.</p></div><FileText className="text-primary" size={22} /></div><div className="mt-5 space-y-3">{resumesQuery.isLoading ? <p className="rounded-2xl bg-muted p-4 text-sm text-muted-foreground">Loading saved CVs…</p> : resumes.length ? resumes.map((resume) => <label key={resume.id} className={`flex cursor-pointer items-center gap-3 rounded-2xl border p-4 transition-colors ${selectedResumeId === resume.id && !file ? 'border-primary bg-[#f5f0f7]' : 'border-border hover:bg-muted'}`}><input type="radio" checked={selectedResumeId === resume.id && !file} onChange={() => { setSelectedResumeId(resume.id); setFile(null); }} className="accent-[hsl(var(--primary))]" data-testid={`radio-resume-${resume.id}`} /><span><span className="block text-sm font-bold">{resume.name}</span><span className="mt-1 block text-xs text-muted-foreground">{resume.isMaster ? 'Master CV' : 'Saved CV'} · {new Date(resume.createdAt).toLocaleDateString()}</span></span></label>) : <p className="rounded-2xl border border-dashed border-border p-4 text-sm text-muted-foreground">No saved CV yet. Upload one below to keep it available for future applications.</p>}<label className={`flex cursor-pointer items-center gap-3 rounded-2xl border p-4 transition-colors ${file ? 'border-primary bg-[#f5f0f7]' : 'border-border hover:bg-muted'}`}><input type="file" accept=".pdf,.docx,.txt,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" className="sr-only" onChange={(e) => selectFile(e.target.files?.[0] || null)} data-testid="input-upload-cv" /><span className="grid h-9 w-9 place-items-center rounded-xl bg-muted"><Upload size={16} /></span><span><span className="block text-sm font-bold">{file?.name || 'Upload a different CV'}</span><span className="mt-1 block text-xs text-muted-foreground">PDF, DOCX, or TXT · up to 10 MB</span></span></label>{processingMessage && <p className="text-sm font-semibold text-primary" role="status" data-testid="text-cv-processing">{processingMessage}</p>}{uploadError && <p className="text-sm font-semibold text-[#ad4c31]" role="alert">{uploadError}</p>}</div></section><div className="flex flex-col-reverse gap-3 sm:flex-row sm:justify-end"><Link href="/applications" className="focus-ring inline-flex items-center justify-center rounded-xl px-5 py-3 text-sm font-bold text-muted-foreground hover:bg-muted" data-testid="link-cancel-new">Cancel</Link><Button type="submit" className="px-6" disabled={processingState !== 'idle' || create.isPending || requestUpload.isPending || resumesQuery.isLoading} data-testid="button-create-workspace">{processingMessage || 'Create workspace'} {processingMessage ? <Clock3 size={16} /> : <ArrowRight size={16} />}</Button></div></form></div></Shell>;
}

function Field({ label, value, onChange, placeholder, required, testId }: { label: string; value: string; onChange: (value: string) => void; placeholder: string; required?: boolean; testId: string }) { return <label className="block"><span className="mb-2 block text-xs font-bold">{label}{required && <span className="text-accent"> *</span>}</span><input required={required} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} className="w-full rounded-xl border border-input bg-background px-3.5 py-3 text-sm outline-none transition-shadow focus:border-primary focus:ring-2 focus:ring-primary/10" data-testid={testId} /></label>; }

function AppWorkspace({ tab = 'overview' }: { tab?: string }) {
  const params = useParams<{ id: string }>(); const id = params.id || 'atlas-01';
  const detailQuery = useGetApplication(id, { query: { enabled: Boolean(id), queryKey: getGetApplicationQueryKey(id) } });
  if (detailQuery.isLoading) return <Shell><LoadingState /></Shell>;
  if (!detailQuery.data) return <Shell><ErrorState onRetry={() => detailQuery.refetch()} /></Shell>;
  const detail = detailQuery.data as ApplicationDetail;
  const tabs = [{ key: 'overview', label: 'Overview', icon: LayoutDashboard }, { key: 'match', label: 'Match analysis', icon: Target }, { key: 'recommendations', label: 'Recommendations', icon: Lightbulb }, { key: 'cv', label: 'Tailored CV', icon: FileText }, { key: 'interview', label: 'Interview prep', icon: Mic2 }];
  return <Shell><div className="animate-reveal space-y-7"><Link href="/applications" className="inline-flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-foreground" data-testid="link-workspace-back"><ChevronRight className="rotate-180" size={15} /> All applications</Link><div className="flex flex-col gap-5 md:flex-row md:items-center md:justify-between"><div className="flex items-center gap-4"><div className="grid h-14 w-14 place-items-center rounded-2xl text-sm font-bold" style={{ background: `${detail.accent || '#8C7EE5'}2c`, color: detail.accent || '#5140a2' }}>{detail.initials || 'AT'}</div><div><div className="flex flex-wrap items-center gap-2"><h1 className="font-display text-3xl font-bold tracking-[-.06em]">{detail.jobTitle}</h1><StatusPill status={detail.status} /></div><p className="mt-1 text-sm text-muted-foreground">{detail.companyName} · {detail.location}</p></div></div><div className="flex items-center gap-3"><div className="hidden text-right sm:block"><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Match score</p><p className="text-lg font-bold text-primary">{detail.matchScore}%</p></div><Link href={`/applications/${id}/interview`} className="focus-ring inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-workspace-practice"><Mic2 size={15} /> Practice interview</Link></div></div><div className="flex gap-1 overflow-x-auto border-b border-border pb-px">{tabs.map(({ key, label, icon: TabIcon }) => <Link key={key} href={`/applications/${id}${key === 'overview' ? '' : `/${key}`}`} className={`focus-ring flex shrink-0 items-center gap-2 border-b-2 px-3 py-3 text-sm font-bold transition-colors ${tab === key ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'}`} data-testid={`tab-${key}`}><TabIcon size={15} />{label}{key === 'recommendations' && <span className="rounded-full bg-accent px-1.5 py-0.5 text-[10px] text-accent-foreground">{detail.acceptedCount + detail.rejectedCount}</span>}</Link>)}</div>{tab === 'overview' && <Overview detail={detail} id={id} />}{tab === 'match' && <Match detail={detail} />}{tab === 'recommendations' && <Recommendations id={id} detail={detail} />}{tab === 'cv' && <CV detail={detail} />}{tab === 'interview' && <Interview id={id} />}</div></Shell>;
}

function Overview({ detail, id }: { detail: ApplicationDetail; id: string }) { return <div className="grid gap-6 lg:grid-cols-[1.25fr_.75fr]"><div className="space-y-6"><section className="rounded-3xl border border-border bg-card p-6 shadow-sm md:p-8"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">A clearer read</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em]">Why this role could be yours</h2></div><Sparkles className="text-accent" size={22} /></div><p className="mt-5 text-sm leading-7 text-muted-foreground">{detail.summary}</p><div className="mt-7 grid gap-6 border-t border-border pt-6 md:grid-cols-2"><div><p className="text-xs font-bold text-[#236a58]">Your strongest signals</p><ul className="mt-3 space-y-2.5">{detail.strengths.slice(0, 4).map((s: string) => <li key={s} className="flex gap-2 text-sm"><Check size={16} className="mt-0.5 shrink-0 text-[#77b5a5]" />{s}</li>)}</ul></div><div><p className="text-xs font-bold text-[#ad4c31]">Worth strengthening</p><ul className="mt-3 space-y-2.5">{detail.gaps.slice(0, 3).map((s: string) => <li key={s} className="flex gap-2 text-sm"><ArrowUpRight size={16} className="mt-0.5 shrink-0 text-[#e38a6b]" />{s}</li>)}</ul></div></div></section><section className="rounded-3xl border border-border bg-card p-6 shadow-sm md:p-8"><div className="flex items-center justify-between"><div><h2 className="font-display text-xl font-bold tracking-[-.04em]">Your path from here</h2><p className="mt-1 text-xs text-muted-foreground">Three small moves, no busywork.</p></div><Clock3 className="text-muted-foreground" size={19} /></div><div className="mt-6 grid gap-3 md:grid-cols-3"><PathCard href={`/applications/${id}/match`} icon={Target} title="Understand your fit" copy="See what’s carrying the score." /><PathCard href={`/applications/${id}/recommendations`} icon={Lightbulb} title="Tune your story" copy="Review 3 explainable edits." /><PathCard href={`/applications/${id}/interview`} icon={Mic2} title="Practice the ask" copy="Warm up with role-specific questions." /></div></section></div><aside className="space-y-6"><section className="rounded-3xl bg-[#2e2855] p-6 text-[#f8f2e8]"><p className="text-xs font-bold uppercase tracking-[.16em] text-[#c7bff2]">Match score</p><div className="mt-5 flex items-center gap-5"><ScoreRing score={detail.matchScore} size="lg" /><div><p className="font-display text-xl font-bold">A compelling fit</p><p className="mt-1 text-xs leading-5 text-[#c7bff2]">Your experience meets the core of this role.</p></div></div><Link href={`/applications/${id}/match`} className="mt-6 inline-flex items-center gap-2 text-sm font-bold text-[#f3b38d]" data-testid="link-see-match">See the breakdown <ArrowRight size={14} /></Link></section><section className="rounded-3xl border border-border bg-card p-6 shadow-sm"><p className="text-xs font-bold uppercase tracking-[.16em] text-muted-foreground">Workspace details</p><div className="mt-5 space-y-4 text-sm"><div className="flex justify-between gap-4"><span className="text-muted-foreground">Source CV</span><span className="max-w-[160px] truncate text-right font-bold">{detail.resumeName}</span></div><div className="flex justify-between gap-4"><span className="text-muted-foreground">Last updated</span><span className="font-bold">Today</span></div><div className="flex justify-between gap-4"><span className="text-muted-foreground">CV suggestions</span><span className="font-bold text-primary">{detail.acceptedCount + detail.rejectedCount} reviewed</span></div></div></section></aside></div>; }
function PathCard({ href, icon: PathIcon, title, copy }: { href: string; icon: Icon; title: string; copy: string }) { return <Link href={href} className="group rounded-2xl border border-border p-4 transition-all hover:-translate-y-1 hover:border-primary/40 hover:shadow-md" data-testid={`link-path-${title.toLowerCase().replaceAll(' ', '-')}`}><PathIcon size={18} className="text-primary" /><p className="mt-8 text-sm font-bold">{title}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{copy}</p><ArrowRight size={15} className="mt-4 text-muted-foreground transition-transform group-hover:translate-x-1" /></Link>; }

function Match({ detail }: { detail: ApplicationDetail }) { const breakdown = Object.entries(detail.scoreBreakdown || {}); return <div className="grid gap-6 lg:grid-cols-[1fr_.75fr]"><section className="rounded-3xl border border-border bg-card p-6 shadow-sm md:p-8"><div className="flex flex-col gap-6 sm:flex-row sm:items-center"><ScoreRing score={detail.matchScore} size="lg" /><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Explainable, not mysterious</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em]">Your match has shape.</h2><p className="mt-2 max-w-lg text-sm leading-6 text-muted-foreground">The score reflects where your experience meets this role — and where a little more proof could make the story stronger.</p></div></div><div className="mt-9 space-y-5 border-t border-border pt-7">{breakdown.map(([label, value]) => <div key={label}><div className="mb-2 flex items-center justify-between text-sm"><span className="font-bold">{label}</span><span className="font-bold text-primary">{value}%</span></div><div className="h-2 rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{ width: `${value}%` }} /></div></div>)}</div></section><section className="rounded-3xl border border-border bg-[#e7f4ef] p-6 md:p-8"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#cce7dc] text-[#236a58]"><Target size={18} /></div><h2 className="font-display text-xl font-bold">Read it like a human</h2></div><p className="mt-6 text-sm leading-7 text-[#365d52]">You don’t need to close every gap before you apply. Use this view to choose the one or two signals worth making louder.</p><div className="mt-7 border-t border-[#bfddd1] pt-5"><p className="text-xs font-bold uppercase tracking-wider text-[#236a58]">Best next move</p><p className="mt-2 text-sm font-bold">Add the dashboard redesign outcome to your CV.</p></div></section></div>; }

function Recommendations({ id, detail }: { id: string; detail: ApplicationDetail }) { const query = useGetRecommendations(id, { query: { enabled: Boolean(id), queryKey: getGetRecommendationsQueryKey(id) } }); const update = useUpdateRecommendation(); const recs: Recommendation[] = (query.data || []) as Recommendation[]; const change = (rec: Recommendation, status: 'accepted' | 'rejected') => { update.mutate({ recommendationId: rec.id, data: { status } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetRecommendationsQueryKey(id) }) }); }; return <div className="space-y-6"><section className="rounded-3xl border border-border bg-card p-6 shadow-sm md:p-8"><div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Your call, always</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em]">Recommendations with receipts</h2><p className="mt-2 text-sm text-muted-foreground">Accept what sounds like you. Reject what doesn’t. The genie is here to suggest, not take over.</p></div><div className="flex gap-3 text-center"><div><p className="font-display text-2xl font-bold text-[#236a58]">{detail.acceptedCount}</p><p className="text-[10px] font-bold uppercase text-muted-foreground">Accepted</p></div><div className="border-l border-border pl-3"><p className="font-display text-2xl font-bold text-[#ad4c31]">{detail.rejectedCount}</p><p className="text-[10px] font-bold uppercase text-muted-foreground">Passed</p></div></div></div></section>{recs.length ? recs.map((rec: Recommendation, index: number) => <section key={rec.id} className="rounded-3xl border border-border bg-card p-5 shadow-sm md:p-7" data-testid={`recommendation-${rec.id}`}><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><span className="grid h-7 w-7 place-items-center rounded-lg bg-[#eeeafd] text-xs font-bold text-primary">{index + 1}</span><span className="text-xs font-bold uppercase tracking-wider text-muted-foreground">{rec.section}</span><span className={`rounded-full px-2 py-1 text-[10px] font-bold ${rec.risk === 'high' ? 'bg-[#fae8e6] text-[#9b423b]' : rec.risk === 'medium' ? 'bg-[#fff4d9] text-[#85631f]' : 'bg-[#e7f4ef] text-[#236a58]'}`}>{rec.risk} risk</span></div><span className={`text-xs font-bold ${rec.status === 'accepted' ? 'text-[#236a58]' : rec.status === 'rejected' ? 'text-[#9b423b]' : 'text-muted-foreground'}`}>{rec.status === 'pending' ? 'Needs your read' : rec.status === 'accepted' ? 'Accepted' : 'Passed for now'}</span></div><div className="mt-6 grid gap-4 md:grid-cols-2"><div className="rounded-2xl bg-muted p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Your original</p><p className="mt-3 text-sm leading-6 text-muted-foreground">{rec.originalText}</p></div><div className="rounded-2xl border border-[#d8d0f0] bg-[#f7f4fb] p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-primary">Suggested version</p><p className="mt-3 text-sm font-semibold leading-6">{rec.suggestedText}</p></div></div><div className="mt-5 flex flex-col gap-4 border-t border-border pt-5 md:flex-row md:items-end md:justify-between"><div className="max-w-2xl"><p className="text-xs font-bold">Why this helps</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{rec.reason}</p><div className="mt-2 flex flex-wrap gap-1.5">{rec.evidence.map((item: string) => <span key={item} className="rounded-full bg-muted px-2 py-1 text-[10px] font-bold text-muted-foreground">{item}</span>)}</div></div>{rec.status === 'pending' && <div className="flex gap-2"><Button variant="secondary" className="text-xs" onClick={() => change(rec, 'rejected')} data-testid={`button-reject-${rec.id}`}><X size={14} /> Pass</Button><Button variant="primary" className="text-xs" onClick={() => change(rec, 'accepted')} data-testid={`button-accept-${rec.id}`}><Check size={14} /> Use this</Button></div>}</div></section>) : <div className="rounded-3xl border border-dashed border-border bg-card p-12 text-center text-sm text-muted-foreground">Recommendations will appear here once this role has been analyzed.</div>}</div>; }

function CV({ detail }: { detail: ApplicationDetail }) { const [downloaded, setDownloaded] = useState(false); return <div className="grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><section className="rounded-3xl border border-border bg-card p-6 shadow-sm md:p-8"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Version 3 · Product-led</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em]">A sharper version of your story</h2></div><FileText className="text-primary" /></div><p className="mt-5 text-sm leading-6 text-muted-foreground">Your tailored CV keeps your voice, while bringing the evidence Atlas is most likely to look for to the front.</p><div className="mt-7 space-y-3"><Button className="w-full" onClick={() => setDownloaded(true)} data-testid="button-export-cv"><Send size={15} /> {downloaded ? 'Export ready' : 'Export PDF'}</Button><Button variant="secondary" className="w-full" onClick={() => window.print()} data-testid="button-print-cv"><ArrowUpRight size={15} /> Print preview</Button></div><div className="mt-8 border-t border-border pt-6"><p className="text-xs font-bold">Version history</p><div className="mt-4 space-y-4 text-xs"><div className="flex items-center justify-between"><span className="font-bold">v3 · Product-led</span><span className="text-[#236a58]">Current</span></div><div className="flex items-center justify-between text-muted-foreground"><span>v2 · Research focus</span><span>Mar 12</span></div><div className="flex items-center justify-between text-muted-foreground"><span>v1 · Original</span><span>Mar 08</span></div></div></div></section><section className="overflow-hidden rounded-3xl border border-border bg-[#e8e1d9] p-4 shadow-sm md:p-8"><div className="mx-auto max-w-[620px] bg-[#fffdf9] px-7 py-8 shadow-xl md:px-12 md:py-10"><div className="border-b-2 border-[#2e2855] pb-5"><h1 className="font-display text-3xl font-bold tracking-[-.06em]">Maya Chen</h1><p className="mt-1 text-sm text-[#5c5870]">Product Designer · New York, NY · maya.chen@email.com</p></div><div className="mt-6"><p className="text-[10px] font-bold uppercase tracking-[.18em] text-[#5140a2]">Profile</p><p className="mt-2 text-xs leading-5">Product designer who makes complex products feel obvious — from first research question to shipped system.</p></div><div className="mt-6"><p className="text-[10px] font-bold uppercase tracking-[.18em] text-[#5140a2]">Experience</p><p className="mt-3 text-sm font-bold">Senior Product Designer · Atlas Studio</p><p className="mt-1 text-[11px] text-[#5c5870]">2021 — Present · New York</p><p className="mt-2 border-l-2 border-[#f28a6a] pl-3 text-xs leading-5">Led the redesign of a multi-role dashboard, reducing task completion time by 31% across 4,200 weekly users.</p><p className="mt-4 text-sm font-bold">Product Designer · Northstar</p><p className="mt-1 text-[11px] text-[#5c5870]">2018 — 2021 · Brooklyn</p><p className="mt-2 text-xs leading-5">Built a research practice across three product squads and translated customer insight into shipped product direction.</p></div><div className="mt-6"><p className="text-[10px] font-bold uppercase tracking-[.18em] text-[#5140a2]">Skills</p><p className="mt-2 text-xs leading-5">Product strategy · Design systems · Qualitative research · Workshop facilitation · Figma</p></div></div></section></div>; }

function Interview({ id }: { id: string }) { const start = useStartInterview(); const submit = useSubmitInterviewAnswer(); const [session, setSession] = useState<InterviewSession | null>(null); const [answer, setAnswer] = useState(''); const [evaluation, setEvaluation] = useState<InterviewEvaluation | null>(null); const startSession = () => start.mutate({ applicationId: id }, { onSuccess: (result: InterviewSession) => setSession(result) }); const current = session || demoSession; const submitAnswer = () => { if (!session || !answer.trim()) return; submit.mutate({ interviewId: session.id, data: { answer } }, { onSuccess: (result: InterviewEvaluation) => { setEvaluation(result); setSession(result.nextQuestion); setAnswer(''); }, onError: () => setAnswer('') }); }; return <div className="grid gap-6 lg:grid-cols-[1fr_.72fr]"><section className="rounded-3xl border border-border bg-card p-6 shadow-sm md:p-8"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Role-specific mock interview</p><p className="mt-2 text-xs font-bold text-muted-foreground">Question {current.questionIndex} of {current.totalQuestions} · {current.category}</p></div><span className="rounded-full bg-[#fff4d9] px-3 py-1.5 text-[11px] font-bold text-[#85631f]">{current.difficulty}</span></div><div className="mt-8 h-1.5 rounded-full bg-muted"><div className="h-full rounded-full bg-accent transition-all" style={{ width: `${(current.questionIndex / current.totalQuestions) * 100}%` }} /></div><h2 className="mt-8 font-display text-3xl font-bold leading-tight tracking-[-.055em]">{current.question}</h2><textarea value={answer} onChange={(e) => setAnswer(e.target.value)} disabled={Boolean(evaluation) || !session} className="mt-8 min-h-44 w-full resize-y rounded-2xl border border-input bg-background p-4 text-sm leading-6 outline-none focus:border-primary focus:ring-2 focus:ring-primary/10 disabled:opacity-60" placeholder={session ? "Take a breath, then write how you’d say it out loud." : "Start a session when you’re ready to practice."} data-testid="input-interview-answer" />{evaluation ? <div className="mt-5 rounded-2xl bg-[#e7f4ef] p-4"><div className="flex items-center justify-between"><p className="text-sm font-bold text-[#236a58]">That landed well.</p><span className="font-display text-2xl font-bold text-[#236a58]">{evaluation.score}/100</span></div><div className="mt-4 grid gap-4 sm:grid-cols-2"><div><p className="text-[10px] font-bold uppercase tracking-wider text-[#236a58]">What worked</p>{evaluation.strengths.map((s: string) => <p key={s} className="mt-2 text-xs leading-5 text-[#365d52]">+ {s}</p>)}</div><div><p className="text-[10px] font-bold uppercase tracking-wider text-[#236a58]">Try next time</p>{evaluation.improvements.map((s: string) => <p key={s} className="mt-2 text-xs leading-5 text-[#365d52]">· {s}</p>)}</div></div><Button className="mt-5" onClick={() => setEvaluation(null)} data-testid="button-next-question">Next question <ArrowRight size={15} /></Button></div> : <div className="mt-5 flex flex-wrap items-center justify-between gap-3"><p className="text-xs text-muted-foreground">Aim for 60–90 seconds. Specific beats perfect.</p><Button onClick={submitAnswer} disabled={!session || !answer.trim() || submit.isPending} data-testid="button-submit-answer">{submit.isPending ? 'Reading your answer…' : <>Get feedback <ArrowRight size={15} /></>}</Button></div>}</section><aside className="space-y-6"><section className="rounded-3xl bg-[#2e2855] p-6 text-[#f8f2e8]"><div className="flex items-center justify-between"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#4d4678]"><Mic2 size={18} className="text-[#f3b38d]" /></div>{!session && <button onClick={startSession} className="text-xs font-bold text-[#f3b38d] hover:text-white" data-testid="button-start-session">{start.isPending ? 'Starting…' : 'Start fresh'}</button>}</div><h2 className="mt-7 font-display text-2xl font-bold tracking-[-.04em]">The signal to practice</h2><p className="mt-3 text-sm leading-6 text-[#c7bff2]">Strong answers here show how you think, not just what you shipped.</p><div className="mt-6 space-y-3">{current.preparationSignals.map((signal: string, index: number) => <div className="flex items-center gap-3 text-xs" key={signal}><span className="grid h-6 w-6 place-items-center rounded-full bg-[#4d4678] font-bold text-[#f3b38d]">{index + 1}</span>{signal}</div>)}</div></section><section className="rounded-3xl border border-border bg-card p-6 shadow-sm"><div className="flex items-center gap-2"><GraduationCap size={17} className="text-primary" /><h3 className="text-sm font-bold">A kinder rule</h3></div><p className="mt-3 text-xs leading-5 text-muted-foreground">You’re not trying to sound polished. You’re giving the other person enough detail to see how you work.</p></section></aside></div>; }

function Profile() { const [saved, setSaved] = useState(false); return <Shell><div className="mx-auto max-w-4xl animate-reveal space-y-7"><PageHeading eyebrow="Your point of view" title="My profile" description="Keep the context that helps the genie give you better advice." action={<Button onClick={() => setSaved(true)} data-testid="button-save-profile">{saved ? <><Check size={16} /> Saved</> : 'Save changes'}</Button>} /><section className="rounded-3xl border border-border bg-card p-6 shadow-sm md:p-8"><div className="flex items-center gap-4 border-b border-border pb-7"><div className="grid h-16 w-16 place-items-center rounded-2xl bg-[#e2c7bc] text-lg font-bold text-[#593f40]">MC</div><div><h2 className="font-display text-xl font-bold">Maya Chen</h2><p className="text-sm text-muted-foreground">Product designer · New York, NY</p></div><button className="ml-auto rounded-xl p-2 text-muted-foreground hover:bg-muted" data-testid="button-edit-avatar"><PenLine size={16} /></button></div><div className="mt-7 grid gap-5 md:grid-cols-2"><Field label="First name" value="Maya" onChange={() => undefined} placeholder="" testId="input-profile-first-name" /><Field label="Email" value="maya.chen@email.com" onChange={() => undefined} placeholder="" testId="input-profile-email" /></div><label className="mt-5 block"><span className="mb-2 block text-xs font-bold">Career headline</span><input defaultValue="Product designer who makes complex products feel obvious." className="w-full rounded-xl border border-input bg-background px-3.5 py-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/10" data-testid="input-profile-headline" /></label></section><section className="rounded-3xl border border-border bg-card p-6 shadow-sm md:p-8"><div className="flex items-center gap-3"><Settings2 size={18} className="text-primary" /><div><h2 className="font-display text-xl font-bold">Preferences</h2><p className="mt-1 text-xs text-muted-foreground">Shape the kind of guidance you want to receive.</p></div></div><div className="mt-7 space-y-5"><Preference title="Be direct with my gaps" copy="Show me what’s missing, with a concrete way to improve it." checked /><Preference title="Keep my voice intact" copy="Prefer suggestions that sound human over suggestions packed with keywords." checked /><Preference title="Nudge me to practice" copy="Remind me when an interview path has been waiting for attention." /></div></section></div></Shell>; }
function Preference({ title, copy, checked = false }: { title: string; copy: string; checked?: boolean }) { const [on, setOn] = useState(checked); return <label className="flex cursor-pointer items-start justify-between gap-4"><span><span className="block text-sm font-bold">{title}</span><span className="mt-1 block text-xs leading-5 text-muted-foreground">{copy}</span></span><button type="button" onClick={() => setOn(!on)} className={`relative mt-1 h-6 w-11 shrink-0 rounded-full transition-colors ${on ? 'bg-primary' : 'bg-muted'}`} aria-pressed={on} data-testid={`toggle-${title.toLowerCase().replaceAll(' ', '-')}`}><span className={`absolute top-1 h-4 w-4 rounded-full bg-card transition-transform ${on ? 'left-6' : 'left-1'}`} /></button></label>; }

function AppRouter() { return <Switch><Route path="/" component={Landing} /><Route path="/dashboard" component={Dashboard} /><Route path="/applications/new" component={NewApplication} /><Route path="/applications/:id/match"><AppWorkspace tab="match" /></Route><Route path="/applications/:id/recommendations"><AppWorkspace tab="recommendations" /></Route><Route path="/applications/:id/cv"><AppWorkspace tab="cv" /></Route><Route path="/applications/:id/interview"><AppWorkspace tab="interview" /></Route><Route path="/applications/:id"><AppWorkspace /></Route><Route path="/applications" component={Applications} /><Route path="/profile" component={Profile} /><Route component={NotFound} /></Switch>; }

function AuthenticatedApp() {
  const { isLoading, isAuthenticated } = useAuth();
  const [location] = useLocation();
  if (isLoading) return <LoadingState />;
  return isAuthenticated ? <AppRouter /> : location.startsWith('/auth') ? <AuthScreen /> : <Landing />;
}

function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><ErrorBoundary><AuthenticatedApp /></ErrorBoundary><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;